const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const storageKey = 'focus-space-state-v1';
const nowISO = () => new Date().toISOString();
const dayKey = d => new Date(d).toISOString().slice(0,10);
const uid = p => `${p}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
const scenes = [
  {id:'warm',name:'Warm Study',desc:'Soft light · steady pace',img:'/assets/warm-study.svg',tone:'#8e654e'},
  {id:'deep',name:'Deep Work',desc:'Low light · low noise',img:'/assets/deep-work.svg',tone:'#435b63'},
  {id:'reading',name:'Reading Room',desc:'Quiet pages · open mind',img:'/assets/reading-room.svg',tone:'#788678'},
  {id:'rainy',name:'Rainy Retreat',desc:'Slow weather · clear thoughts',img:'/assets/rainy-retreat.svg',tone:'#5f7b80'},
  {id:'morning',name:'Morning Planning',desc:'Bright start · gentle momentum',img:'/assets/morning-planning.svg',tone:'#c69763'}
];
const defaultState = {
  theme:'light', scene:'warm', timerStyle:'minimal', preset:25, encouragement:true, reduceMotion:false,
  tasks:[
    {id:'t1',title:'Shape the afternoon brief',tag:'Work',done:false},
    {id:'t2',title:'Reply to Maya about Thursday',tag:'Inbox',done:false},
    {id:'t3',title:'10 min desk reset',tag:'Personal',done:true}
  ],
  schedule:[
    {id:'s1',time:'10:30',title:'Product sync',meta:'Studio / 30 min'},
    {id:'s2',time:'13:00',title:'Lunch + outside',meta:'Unscheduled / 45 min'},
    {id:'s3',time:'15:30',title:'Quiet writing block',meta:'Focus / 60 min'}
  ], notes:'', fullNote:'', sessions:[], timer:{mode:'focus',phase:'idle',duration:1500,startedAt:null,elapsedBeforeStart:0,sessionId:null}
};
let state = loadState();
let tickHandle = null;
let toastTimer = null;
function loadState(){try{return {...defaultState,...JSON.parse(localStorage.getItem(storageKey)||'{}'),timer:{...defaultState.timer,...(JSON.parse(localStorage.getItem(storageKey)||'{}').timer||{})}}}catch{return structuredClone(defaultState)}}
function saveState(){localStorage.setItem(storageKey,JSON.stringify(state)); updateSync('Saved locally');}
function updateSync(text, mode='ok'){const pill=$('#syncPill'), label=$('#syncText'), dot=$('.sync-dot',pill); if(!pill)return; label.textContent=text; dot.style.background=mode==='sync'?'#c6a56b':mode==='offline'?'#ad8b75':'#719c84';}
function showToast(message){$('#toastText').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2100)}
function formatTime(seconds){seconds=Math.max(0,Math.round(seconds));const m=Math.floor(seconds/60).toString().padStart(2,'0'),s=(seconds%60).toString().padStart(2,'0');return `${m}:${s}`}
function currentElapsed(){const t=state.timer; return Math.max(0,t.elapsedBeforeStart+(t.phase==='running'&&t.startedAt?((Date.now()-t.startedAt)/1000):0))}
function timerProgress(){const t=state.timer;return Math.min(1,currentElapsed()/t.duration)}
function renderTimer(){const t=state.timer, elapsed=currentElapsed(), remaining=Math.max(0,t.duration-elapsed), display=t.mode==='focus'?remaining:remaining; const text=formatTime(t.phase==='idle'&&t.mode==='focus'&&elapsed===0?t.duration:display); $('#timerReadout').textContent=text; $('#overlayTimer').textContent=text; const label=t.mode==='focus'?'Deep work':t.mode==='short'?'Short break':'Long break'; $('#timerModeLabel').textContent=label; $('#timerStatus').textContent=t.phase==='running'?'In focus':t.phase==='paused'?'Paused':'Ready to focus'; $('#startLabel').textContent=t.phase==='running'?'Pause':t.phase==='paused'?'Resume':'Start focus'; $('#startIcon').textContent=t.phase==='running'?'Ⅱ':'▶'; $('#overlayStart').textContent=t.phase==='running'?'Ⅱ Pause':t.phase==='paused'?'▶ Resume':'▶ Start focus'; const pct=Math.round(timerProgress()*360); $('.orbit-ring').style.setProperty('--progress',`${pct}deg`); $('.orbit-ring').style.background=`conic-gradient(var(--accent) ${pct}deg, transparent ${pct}deg)`; $('.orbit-ring').style.mask='radial-gradient(farthest-side,transparent calc(100% - 8px),#000 0)'; $('.orbit-ring').style.webkitMask='radial-gradient(farthest-side,transparent calc(100% - 8px),#000 0)'; const caption=t.phase==='running'?(state.encouragement?'Stay with this one thing.':''):t.phase==='paused'?'Paused. Come back when you are ready.':'A quiet start is still a start.'; $('#timerCaption').textContent=caption; $('#overlayCaption').textContent=caption;}
function timerLoop(){renderTimer(); if(state.timer.phase==='running'){const elapsed=currentElapsed(); if(elapsed>=state.timer.duration){completeSession(true);return} tickHandle=requestAnimationFrame(timerLoop)}}
function startPause(){const t=state.timer;if(t.phase==='running'){t.elapsedBeforeStart=currentElapsed();t.startedAt=null;t.phase='paused';cancelAnimationFrame(tickHandle);saveState();showToast('Focus paused');renderTimer();return} if(t.phase==='paused'){t.startedAt=Date.now();t.phase='running';saveState();timerLoop();showToast('Back to focus');return} t.startedAt=Date.now();t.phase='running';t.sessionId=t.sessionId||uid('session');saveState();timerLoop();showToast('Focus started')}
function resetTimer(force=false){const elapsed=currentElapsed(); if(!force&&elapsed>1&&state.timer.phase!=='idle'){openConfirmReset();return} state.timer={...state.timer,phase:'idle',startedAt:null,elapsedBeforeStart:0,sessionId:null};saveState();renderTimer();showToast('Timer reset')}
function stopTimer(){if(state.timer.phase==='idle'){showToast('Nothing to stop yet');return} completeSession(false)}
function skipPhase(){if(state.timer.mode==='focus'&&currentElapsed()>0){if(!confirm('Skip this focus session without saving it?'))return} state.timer={...state.timer,phase:'idle',startedAt:null,elapsedBeforeStart:0,sessionId:null};saveState();renderTimer();showToast('Phase skipped')}
function completeSession(auto){const t=state.timer;const actual=Math.max(0,Math.round(currentElapsed())); if(t.mode==='focus'&&actual>0){const session={id:t.sessionId||uid('session'),startedAt:new Date((t.startedAt||Date.now())-Math.min(actual,t.duration)*1000).toISOString(),endedAt:nowISO(),date:dayKey(Date.now()),plannedSeconds:t.duration,actualSeconds:Math.min(actual,t.duration),intention:'',outcome:'',mood:'',interruptions:'',nextStep:'',reflection:'',createdAt:nowISO(),updatedAt:nowISO()};state.sessions.unshift(session);state.timer={...t,phase:'idle',startedAt:null,elapsedBeforeStart:0,sessionId:null};saveState();renderAll();openReflection(session,auto);return} state.timer={...t,phase:'idle',startedAt:null,elapsedBeforeStart:0,sessionId:null};saveState();renderTimer()}
function setMode(mode){if(state.timer.phase==='running'){showToast('Pause the timer before changing mode');return} const presets={focus:state.preset*60,short:5*60,long:15*60};state.timer={...state.timer,mode,duration:presets[mode]||presets.focus,elapsedBeforeStart:0,startedAt:null,phase:'idle',sessionId:null};$$('.seg-button').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));saveState();renderTimer()}
function setPreset(value){if(value==='custom'){openCustomDuration();return}state.preset=Number(value); if(state.timer.phase==='idle'||state.timer.phase==='paused')state.timer.duration=state.timer.mode==='focus'?state.preset*60:state.timer.mode==='short'?300:900; saveState();renderTimer()}
function renderTasks(root=$('#taskList')){if(!root)return;root.innerHTML=state.tasks.map(t=>`<div class="task-row ${t.done?'done':''}" data-id="${t.id}"><button class="task-check" aria-label="Toggle task">✓</button><span class="task-title">${escapeHtml(t.title)}</span><span class="task-tag">${escapeHtml(t.tag||'')}</span></div>`).join('');root.querySelectorAll('.task-row').forEach(row=>$('.task-check',row).addEventListener('click',()=>{const task=state.tasks.find(x=>x.id===row.dataset.id);task.done=!task.done;saveState();renderAll();showToast(task.done?'Task completed':'Task reopened')}))}
function renderSchedule(root=$('#scheduleList')){if(!root)return;root.innerHTML=state.schedule.map(s=>`<div class="schedule-item"><div class="schedule-time">${escapeHtml(s.time)}</div><div class="schedule-title"><span class="schedule-line"></span><strong>${escapeHtml(s.title)}</strong><span>${escapeHtml(s.meta||'')}</span></div></div>`).join('')}
function renderStats(){const sessions=state.sessions, today=dayKey(Date.now()), todaySecs=sessions.filter(s=>s.date===today).reduce((a,s)=>a+s.actualSeconds,0), weekSecs=sessions.reduce((a,s)=>a+s.actualSeconds,0);$('#todayMinutes').textContent=`${Math.round(todaySecs/60)}m`;$('#weekSessions').textContent=sessions.length;$('#streakDays').textContent=sessions.length?Math.min(7,new Set(sessions.map(s=>s.date)).size):1;const bars=$('#weeklyBars');const vals=lastDays(7).map(d=>sessions.filter(s=>s.date===d).reduce((a,s)=>a+s.actualSeconds,0));const max=Math.max(...vals,1800);bars.innerHTML=vals.map((v,i)=>`<i class="${i===6?'today':''} ${v?'active':''}" style="height:${Math.max(10,Math.round((v/max)*100))}%"></i>`).join('')}
function lastDays(n){return Array.from({length:n},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(n-1-i));return dayKey(d)})}
function renderJourney(){const total=state.sessions.reduce((a,s)=>a+s.actualSeconds,0);$('#journeyTotal').textContent=`${Math.floor(total/3600)}h ${Math.round(total%3600/60)}m`;$('#journeyCount').textContent=`${state.sessions.length} session${state.sessions.length===1?'':'s'}`;const vals=lastDays(7).map(d=>state.sessions.filter(s=>s.date===d).reduce((a,s)=>a+s.actualSeconds,0));const max=Math.max(...vals,1800);$('#largeBars').innerHTML=vals.map((v,i)=>`<i class="${i===6?'today':''} ${v?'active':''}" style="height:${Math.max(8,Math.round((v/max)*100))}%"></i>`).join('');const hist=$('#sessionHistory');hist.innerHTML=state.sessions.length?state.sessions.slice(0,8).map(s=>`<div class="session-row"><div><strong>${s.outcome||'Focused session'}</strong><span>${new Date(s.endedAt).toLocaleDateString('en',{month:'short',day:'numeric'})} · ${Math.round(s.actualSeconds/60)} min</span></div><span>${s.mood||'—'}</span></div>`).join(''):'<div class="empty-state">Complete a focus session to see your reflections here.</div>'}
function renderScenes(){const grid=$('#sceneGrid');grid.innerHTML=scenes.map(s=>`<article class="scene-card ${state.scene===s.id?'selected':''}" data-scene="${s.id}"><img src="${s.img}" alt="${s.name} scene"/><span class="scene-check">✓</span><div class="scene-info"><h3>${s.name}</h3><p>${s.desc}</p></div></article>`).join('');grid.querySelectorAll('.scene-card').forEach(c=>c.addEventListener('click',()=>{state.scene=c.dataset.scene;saveState();applyScene();renderScenes();showToast(`${scenes.find(s=>s.id===state.scene).name} applied`)}))}
function applyScene(){const scene=scenes.find(s=>s.id===state.scene)||scenes[0];document.body.style.setProperty('--scene-image',`url(${scene.img})`);$('#overlayScene').textContent=scene.name;document.querySelector('.timer-card').style.backgroundImage=`linear-gradient(145deg,rgba(255,255,253,.89),rgba(247,249,244,.7)),url(${scene.img})`;document.querySelector('.timer-card').style.backgroundSize='cover';document.querySelector('.timer-card').style.backgroundPosition='center'}
function renderAll(){renderTasks($('#taskList'));renderTasks($('#taskListPage'));renderSchedule($('#scheduleList'));renderSchedule($('#scheduleListPage'));renderStats();renderJourney();renderScenes();renderTimer();$('#taskCount').textContent=state.tasks.filter(t=>!t.done).length;$('#quickNote').value=state.notes||'';$('#fullNote').value=state.fullNote||state.notes||'';$('#noteCount').textContent=`${(state.notes||'').length} / 500`;$('#fullNoteCount').textContent=`${(state.fullNote||'').length} / 5000`;applyScene()}
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function openModal(html){$('#modalCard').innerHTML=html;$('#modal').classList.add('open');$('#modal').setAttribute('aria-hidden','false')}
function closeModal(){$('#modal').classList.remove('open');$('#modal').setAttribute('aria-hidden','true')}
function openConfirmReset(){openModal(`<h3>Reset this session?</h3><p>You have already spent ${Math.round(currentElapsed()/60)} minutes here. Resetting will clear this in-progress session without creating a reflection.</p><div class="modal-actions"><button class="secondary-button" data-close-modal>Keep going</button><button class="primary-button" id="confirmReset">Reset session</button></div>`);$('#confirmReset').addEventListener('click',()=>{closeModal();resetTimer(true)})}
function openCustomDuration(){openModal(`<h3>Make a custom focus block</h3><p>Choose a duration that fits the work in front of you.</p><div class="modal-form"><label>Focus minutes<input id="customFocus" type="number" min="1" max="180" value="25"/></label><label>Break minutes<input id="customBreak" type="number" min="1" max="60" value="5"/></label></div><div class="modal-actions"><button class="secondary-button" data-close-modal>Cancel</button><button class="primary-button" id="saveCustom">Use this preset</button></div>`);$('#saveCustom').addEventListener('click',()=>{const f=Math.max(1,Math.min(180,Number($('#customFocus').value)||25));state.preset=f;state.timer.duration=state.timer.mode==='focus'?f*60:Math.max(1,Number($('#customBreak').value)||5)*60;saveState();closeModal();renderTimer();showToast('Custom preset ready')})}
function openReflection(session,auto){openModal(`<p class="eyebrow">${auto?'SESSION COMPLETE':'SESSION ENDED'}</p><h3>What did this time make possible?</h3><p>Your ${Math.round(session.actualSeconds/60)} minute focus block is saved. A few words can help you notice the pattern.</p><div class="modal-form"><label>Outcome<textarea id="reflectionOutcome" placeholder="What moved forward?"></textarea></label><label>Mood<select id="reflectionMood"><option value="">Choose one</option><option>Clear</option><option>Steady</option><option>Restless</option><option>Surprised</option></select></label><label>Next step<input id="reflectionNext" placeholder="What comes next?"/></label></div><div class="modal-actions"><button class="secondary-button" id="skipReflection">Skip for now</button><button class="primary-button" id="saveReflection">Save reflection</button></div>`);$('#skipReflection').addEventListener('click',()=>{closeModal();showToast('Session saved')});$('#saveReflection').addEventListener('click',()=>{session.outcome=$('#reflectionOutcome').value.trim();session.mood=$('#reflectionMood').value;session.nextStep=$('#reflectionNext').value.trim();session.updatedAt=nowISO();saveState();closeModal();renderAll();showToast('Reflection saved')})}
function openAddTask(){openModal(`<h3>Add a task</h3><p>Keep it small enough to start.</p><div class="modal-form"><label>Task<input id="newTaskTitle" autofocus placeholder="What needs your attention?"/></label><label>Area<select id="newTaskTag"><option>Work</option><option>Personal</option><option>Inbox</option></select></label></div><div class="modal-actions"><button class="secondary-button" data-close-modal>Cancel</button><button class="primary-button" id="saveTask">Add task</button></div>`);$('#saveTask').addEventListener('click',()=>{const title=$('#newTaskTitle').value.trim();if(!title)return;state.tasks.push({id:uid('task'),title,tag:$('#newTaskTag').value,done:false});saveState();closeModal();renderAll();showToast('Task added')})}
function openAddSchedule(){openModal(`<h3>Add to your day</h3><p>Give the next block a gentle shape.</p><div class="modal-form"><label>Title<input id="newScheduleTitle" autofocus placeholder="e.g. Review the brief"/></label><label>Time<input id="newScheduleTime" type="time" value="11:00"/></label><label>Duration<input id="newScheduleMeta" placeholder="Focus / 45 min" value="Focus / 45 min"/></label></div><div class="modal-actions"><button class="secondary-button" data-close-modal>Cancel</button><button class="primary-button" id="saveSchedule">Add to schedule</button></div>`);$('#saveSchedule').addEventListener('click',()=>{const title=$('#newScheduleTitle').value.trim();if(!title)return;state.schedule.push({id:uid('schedule'),title,time:$('#newScheduleTime').value||'11:00',meta:$('#newScheduleMeta').value.trim()});state.schedule.sort((a,b)=>a.time.localeCompare(b.time));saveState();closeModal();renderAll();showToast('Schedule updated')})}
function openRitual(){openModal(`<p class="eyebrow">FOCUS RITUAL</p><h3>Arrive before you begin.</h3><p>Take 30 seconds to settle your space. This is optional and will not create a session.</p><div class="ritual-steps"><div>1 <span>Clear one small surface</span></div><div>2 <span>Take three slow breaths</span></div><div>3 <span>Choose one thing to move forward</span></div></div><div class="modal-actions"><button class="secondary-button" data-close-modal>Skip</button><button class="primary-button" id="ritualDone">I’m ready</button></div>`);$('#ritualDone').addEventListener('click',()=>{closeModal();showToast('Your space is ready')})}
function navigate(view){$$('.view').forEach(v=>v.classList.toggle('active',v.id===`${view}View`));$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));window.scrollTo({top:0,behavior:'smooth'})}
function updateClock(){const d=new Date();$('#clockTime').textContent=d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});$('#clockMeta').textContent=d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'}).toUpperCase()}
function toggleFullscreen(){const overlay=$('#focusOverlay');overlay.classList.toggle('open');overlay.setAttribute('aria-hidden',String(!overlay.classList.contains('open')))}
function bind(){document.addEventListener('click',e=>{const close=e.target.closest('[data-close-modal]');if(close){closeModal();return}const view=e.target.closest('[data-view], [data-view-target]');if(view){navigate(view.dataset.view||view.dataset.viewTarget);return}});$('#startButton').addEventListener('click',startPause);$('#overlayStart').addEventListener('click',startPause);$('#resetButton').addEventListener('click',()=>resetTimer());$('#overlayReset').addEventListener('click',()=>resetTimer());$('#overlayStop').addEventListener('click',stopTimer);$('#fullscreenButton').addEventListener('click',toggleFullscreen);$('#exitFullscreen').addEventListener('click',toggleFullscreen);$('#themeToggle').addEventListener('click',()=>{state.theme=state.theme==='light'?'dark':'light';document.body.classList.toggle('dark',state.theme==='dark');saveState()});$('#ritualButton').addEventListener('click',openRitual);$('#addTaskButton').addEventListener('click',openAddTask);$('#addTaskButtonPage').addEventListener('click',openAddTask);$('#addScheduleButton').addEventListener('click',openAddSchedule);$('#addScheduleButtonPage').addEventListener('click',openAddSchedule);$('#openNotesButton').addEventListener('click',()=>navigate('notes'));$('#newNoteButton').addEventListener('click',()=>{$('#fullNote').focus()});$('#presetSelect').addEventListener('change',e=>setPreset(e.target.value));$('#styleSelect').addEventListener('change',e=>{state.timerStyle=e.target.value;$('#timerStage').dataset.style=state.timerStyle;saveState();showToast(`${e.target.options[e.target.selectedIndex].text} selected`)});$$('.seg-button').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));$('#quickNote').addEventListener('input',e=>{state.notes=e.target.value.slice(0,500);$('#noteCount').textContent=`${state.notes.length} / 500`;saveState();$('#noteSaved').textContent='Autosaved just now'});$('#fullNote').addEventListener('input',e=>{state.fullNote=e.target.value.slice(0,5000);$('#fullNoteCount').textContent=`${state.fullNote.length} / 5000`;saveState();$('#fullNoteSaved').textContent='Autosaved just now'});$('#encouragementToggle').addEventListener('change',e=>{state.encouragement=e.target.checked;saveState()});$('#motionToggle').addEventListener('change',e=>{state.reduceMotion=e.target.checked;document.body.classList.toggle('reduce-motion',state.reduceMotion);saveState()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#focusOverlay').classList.contains('open'))toggleFullscreen();if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#editLayoutButton').click()}});$('#editLayoutButton').addEventListener('click',()=>showToast('Layout editing arrives next — your focus stays centered'));window.addEventListener('online',()=>updateSync('Online · synced'));window.addEventListener('offline',()=>updateSync('Offline · saved locally','offline'))}
function init(){document.body.classList.toggle('dark',state.theme==='dark');document.body.classList.toggle('reduce-motion',state.reduceMotion);$('#encouragementToggle').checked=state.encouragement;$('#motionToggle').checked=state.reduceMotion;$('#presetSelect').value=String(state.preset);$('#styleSelect').value=state.timerStyle;$('#timerStage').dataset.style=state.timerStyle;bind();renderAll();updateClock();setInterval(updateClock,1000);if(state.timer.phase==='running'){timerLoop()}else{renderTimer()}if(!navigator.onLine)updateSync('Offline · saved locally','offline');if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
init();
